              <div className={`group relative px-10 py-5 rounded-[2.5rem] text-base font-medium max-w-[85%] leading-relaxed transition-all ${t.type === 'user' ? 'bg-slate-800/60 text-slate-100 border border-white/5' : 'bg-blue-600/5 text-blue-50 border border-blue-500/20 shadow-[0_0_50px_rgba(59,130,246,0.05)]'}`}>
                {t.text}
                <div className={`absolute -bottom-8 flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all ${t.type === 'user' ? 'right-6' : 'left-6'}`}>
                   <span className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-600">
                     {t.type === 'user' ? 'User Transmission' : 'V1 Neural Out'}
                   </span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {error && (
          <div className="flex items-center gap-6 p-8 bg-red-500/5 border border-red-500/10 rounded-[2.5rem] animate-in slide-in-from-top-8 duration-500 shadow-[0_30px_60px_rgba(239,68,68,0.1)]">
            <div className="p-4 bg-red-500/10 rounded-[1.5rem]"><AlertCircle className="text-red-500" size={32} /></div>
            <div className="flex-1 space-y-2">
              <p className="text-red-400 text-xs font-black uppercase tracking-[0.3em]">Critical Exception</p>
              <p className="text-red-200/60 text-sm font-medium leading-relaxed">{error}</p>
            </div>
            {error.includes('Key') && (
              <button onClick={handleSelectKey} className="px-6 py-2 bg-blue-600 text-white text-xs font-black uppercase rounded-full">Reset Key</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default VoiceInteraction;

import React, { useState, useEffect, useRef } from 'react';
import { Mic, MicOff, AlertCircle, Sparkles, Activity, Terminal, ExternalLink, Clock, Power, Key, Cpu, Radio } from 'lucide-react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob, Type, FunctionDeclaration } from '@google/genai';

interface VoiceInteractionProps {
  handlers: {
    addNote: (title: string, content: string) => string;
    addTask: (text: string) => string;
    sendMessage: (recipient: string, text: string) => string;
    getNotifications: () => string;
    controlMedia: (action: string) => string;
    getTime: () => string;
    openUrl: (target: string) => string;
  };
}

const VoiceInteraction: React.FC<VoiceInteractionProps> = ({ handlers }) => {
  const [isListening, setIsListening] = useState(false);
  const [transcription, setTranscription] = useState<{ type: 'user' | 'v1'; text: string }[]>([]);
  const [status, setStatus] = useState<string>('Neural Link Standby');
  const [error, setError] = useState<string | null>(null);
  const [inputLevel, setInputLevel] = useState(0);
  const [needsKey, setNeedsKey] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);

  const currentInputTranscription = useRef('');
  const currentOutputTranscription = useRef('');

  // Initial check for API Key availability
  useEffect(() => {
    const checkKeyAvailability = async () => {
      if (typeof (window as any).aistudio !== 'undefined') {
        try {
          const hasKey = await (window as any).aistudio.hasSelectedApiKey();
          // If no key in process.env AND not selected via platform
          if (!hasKey && (!process.env.API_KEY || process.env.API_KEY === "")) {
            setNeedsKey(true);
          }
        } catch (e) {
          console.error("Key check failed", e);
        }
      }
    };
    checkKeyAvailability();
  }, []);

  const handleOpenKeySelector = async () => {
    if (typeof (window as any).aistudio !== 'undefined') {
      try {
        await (window as any).aistudio.openSelectKey();
        // After opening the dialog, we assume a key will be selected or is available.
        setNeedsKey(false);
        setError(null);
      } catch (e) {
        console.error("Failed to open key selector", e);
      }
    }
  };

  // Manual base64 utilities for raw PCM data
  function encodeBase64(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function decodeBase64(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  // Convert raw PCM to AudioBuffer for playback
  async function pcmToAudioBuffer(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }

  const tools: FunctionDeclaration[] = [
    {
      name: 'add_note',
      parameters: {
        type: Type.OBJECT,
        properties: { 
          title: { type: Type.STRING, description: 'Short title for the note' }, 
          content: { type: Type.STRING, description: 'Descriptive content for the note' } 
        },
        required: ['title', 'content']
      }
    },
    {
      name: 'add_task',
      parameters: {
        type: Type.OBJECT,
        properties: { text: { type: Type.STRING, description: 'The task description' } },
        required: ['text']
      }
    },
    {
      name: 'get_current_time',
      parameters: { type: Type.OBJECT, properties: {} },
      description: 'Get current system time.'
    },
    {
      name: 'open_website',
      parameters: {
        type: Type.OBJECT,
        properties: { 
          target: { type: Type.STRING, description: 'The site name (e.g., Google, YouTube)' } 
        },
        required: ['target']
      }
    },
    {
      name: 'control_multimedia',
      parameters: {
        type: Type.OBJECT,
        properties: { 
          action: { 
            type: Type.STRING, 
            description: 'The media command: "play", "pause", "next", or "capture" (camera)' 
          } 
        },
        required: ['action']
      }
    },
    {
      name: 'stop_assistant',
      parameters: { type: Type.OBJECT, properties: {} },
      description: 'Shutdown the session.'
    }
  ];

  const stopSession = () => {
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(s => s.close()).catch(() => {});
      sessionPromiseRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    [inputAudioContextRef, audioContextRef].forEach(ref => {
      if (ref.current) {
        ref.current.close().catch(() => {});
        ref.current = null;
      }
    });
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
    sourcesRef.current.clear();

    setIsListening(false);
    setStatus('Neural Link Standby');
    setInputLevel(0);
    nextStartTimeRef.current = 0;
  };

  const startSession = async () => {
    try {
      setError(null);

      const apiKey = process.env.API_KEY;
      // Rigorous key check before constructor call
      if (!apiKey || apiKey === "") {
        setNeedsKey(true);
        return;
      }

      setStatus('Synchronizing Frequencies...');

      const AudioCtx = (window.AudioContext || (window as any).webkitAudioContext);
      const inCtx = new AudioCtx({ sampleRate: 16000 });
      const outCtx = new AudioCtx({ sampleRate: 24000 });

      await inCtx.resume();
      await outCtx.resume();

      inputAudioContextRef.current = inCtx;
      audioContextRef.current = outCtx;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      // Safe initialization
      const ai = new GoogleGenAI({ apiKey });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus('V1 Synchronized');
            setIsListening(true);

            const micSource = inCtx.createMediaStreamSource(stream);
            const processor = inCtx.createScriptProcessor(4096, 1, 1);

            processor.onaudioprocess = (e) => {
              const pcmData = e.inputBuffer.getChannelData(0);

              // Metering
              let sum = 0;
              for (let i = 0; i < pcmData.length; i++) sum += Math.abs(pcmData[i]);
              setInputLevel(sum / pcmData.length);

              // PCM Conversion
              const int16 = new Int16Array(pcmData.length);
              for (let i = 0; i < pcmData.length; i++) int16[i] = pcmData[i] * 32768;

              const mediaBlob: Blob = { 
                data: encodeBase64(new Uint8Array(int16.buffer)), 
                mimeType: 'audio/pcm;rate=16000' 
              };
              sessionPromise.then(s => s.sendRealtimeInput({ media: mediaBlob })).catch(() => {});
            };

            micSource.connect(processor);
            processor.connect(inCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Process Output Audio
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && audioContextRef.current) {
              const ctx = audioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await pcmToAudioBuffer(decodeBase64(audioData), ctx, 24000, 1);
              const src = ctx.createBufferSource();
              src.buffer = buffer;
              src.connect(ctx.destination);
              src.onended = () => sourcesRef.current.delete(src);
              src.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(src);
            }

            // Real-time Captions
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscription.current += message.serverContent.outputTranscription.text;
            } else if (message.serverContent?.inputTranscription) {
              currentInputTranscription.current += message.serverContent.inputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const uText = currentInputTranscription.current.trim();
              const aText = currentOutputTranscription.current.trim();
              if (uText || aText) {
                setTranscription(prev => [
                  ...prev, 
                  ...(uText ? [{ type: 'user' as const, text: uText }] : []),
                  ...(aText ? [{ type: 'v1' as const, text: aText }] : [])
                ].slice(-15));
              }
              currentInputTranscription.current = '';
              currentOutputTranscription.current = '';
            }

            // Tool Execution (The V1 Brain)
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                let res: any = "Execution Confirmed";
                try {
                  if (fc.name === 'get_current_time') res = handlers.getTime();
                  else if (fc.name === 'open_website') res = handlers.openUrl(fc.args.target as string);
                  else if (fc.name === 'stop_assistant') {
                    res = "Shutting down system. Farewell.";
                    setTimeout(stopSession, 1500);
                  }
                  else if (fc.name === 'add_note') res = handlers.addNote(fc.args.title as string, fc.args.content as string);
                  else if (fc.name === 'add_task') res = handlers.addTask(fc.args.text as string);
                  else if (fc.name === 'control_multimedia') res = handlers.controlMedia(fc.args.action as string);
                } catch (e) {
                  res = "System Error: " + (e as Error).message;
                }

                sessionPromise.then(s => s.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: res } }]
                }));
              }
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => {
            const msg = e instanceof Error ? e.message : 'Encryption Failure';
            if (msg.includes('Requested entity was not found') || msg.includes('API Key')) {
              setNeedsKey(true);
            }
            setError('Interface Disconnected: ' + msg);
            stopSession();
          },
          onclose: () => {
            setIsListening(false);
            setStatus('Neural Link Standby');
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          tools: [{ functionDeclarations: tools }],
          systemInstruction: "You are V1, a high-intelligence AI assistant. Greet the user with 'Hello, I am your AI assistant'. You handle time, web navigation, multimedia (play, pause, next, capture), and notes/tasks. For 'exit' or 'stop', use the stop_assistant tool and say 'Shutting down system. Farewell.' Be concise, professional, and rapid.",
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err: any) {
      setError('Initialization Error: ' + (err.message || 'HW Access Denied'));
      setStatus('Neural Link Standby');
    }
  };

  useEffect(() => {
    return () => stopSession();
  }, []);

  return (
    <div className="flex flex-col items-center justify-center h-full max-w-5xl mx-auto px-6 gap-10">
      {/* HUD Header */}
      <div className="text-center space-y-4 animate-in fade-in zoom-in duration-1000">
        <div className="flex justify-center relative">
          <div className={`absolute -inset-16 rounded-full bg-blue-500/10 blur-[100px] transition-all duration-1000 ${isListening ? 'opacity-100 scale-125' : 'opacity-0'}`} />
          <div className={`relative p-10 bg-slate-950/80 backdrop-blur-3xl border border-white/5 rounded-[3.5rem] shadow-2xl transition-all duration-700 ${isListening ? 'scale-110 shadow-blue-500/30' : 'grayscale border-slate-800'}`}>
            <Cpu size={64} className={`${isListening ? 'text-blue-400 animate-pulse' : 'text-slate-600'}`} />
          </div>
        </div>
        <div className="space-y-2">
          <h1 className="text-7xl font-black italic tracking-tighter bg-gradient-to-br from-white via-blue-200 to-indigo-600 bg-clip-text text-transparent uppercase">V1 Interface</h1>
          <div className="flex items-center justify-center gap-6 text-slate-600">
             <div className="h-[2px] w-16 bg-gradient-to-r from-transparent to-slate-800" />
             <p className="font-black text-[10px] tracking-[0.6em] uppercase flex items-center gap-2">
               <Radio size={12} className={isListening ? 'animate-pulse text-blue-500' : ''} />
               Secure Connection
             </p>
             <div className="h-[2px] w-16 bg-gradient-to-l from-transparent to-slate-800" />
          </div>
        </div>
      </div>

      {/* Main Core Interaction */}
      <div className="relative flex flex-col items-center gap-12 w-full">
        {needsKey ? (
          <div className="flex flex-col items-center gap-8 animate-in slide-in-from-bottom-8 duration-700">
            <div className="p-12 glass-panel rounded-[4rem] border-blue-500/20 text-center max-w-md space-y-8 bg-slate-900/40">
              <div className="w-20 h-20 bg-blue-600/10 rounded-3xl flex items-center justify-center mx-auto mb-4 border border-blue-500/20 shadow-inner">
                <Key size={40} className="text-blue-400" />
              </div>
              <div className="space-y-2">
                <h3 className="text-2xl font-black uppercase tracking-tight text-white">Neural Handshake Required</h3>
                <p className="text-slate-400 text-sm leading-relaxed font-medium">
                  V1 requires a valid API key from a paid GCP project to authorize high-latency neural interaction.
                </p>
              </div>
              <button 
                onClick={handleOpenKeySelector}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 text-white font-black uppercase tracking-[0.2em] text-xs rounded-3xl shadow-[0_20px_40px_rgba(37,99,235,0.3)] transition-all active:scale-95 flex items-center justify-center gap-4"
              >
                Link Project Key
                <ExternalLink size={16} />
              </button>
              <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="block text-[9px] text-slate-600 hover:text-blue-400 transition-colors uppercase font-black tracking-widest border-t border-white/5 pt-6">
                Consult Billing Documentation
              </a>
            </div>
          </div>
        ) : (
          <button 
            onClick={isListening ? stopSession : startSession}
            className={`relative w-96 h-96 rounded-full flex flex-col items-center justify-center transition-all duration-1000 group ${isListening ? 'bg-blue-600/5 border-2 border-blue-400 shadow-[0_0_150px_rgba(59,130,246,0.3)]' : 'bg-slate-900/40 border-2 border-slate-800 hover:border-blue-500/40 hover:bg-slate-950 shadow-2xl'}`}
          >
            {isListening ? (
              <div className="flex gap-3 h-32 items-center">
                {[...Array(24)].map((_, i) => (
                  <div 
                    key={i} 
                    className="w-1.5 bg-blue-400 rounded-full animate-bounce" 
                    style={{ 
                      height: `${15 + Math.random() * 85}%`, 
                      animationDelay: `${i * 0.04}s`,
                      opacity: 0.1 + (inputLevel * 25)
                    }} 
                  />
                ))}
              </div>
            ) : (
              <div className="relative">
                <div className="absolute inset-0 bg-blue-500/20 blur-3xl rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
                <Mic size={110} className="text-slate-700 group-hover:text-blue-400 transition-all duration-1000 transform group-hover:scale-110" />
              </div>
            )}
            <div className="absolute bottom-20 flex flex-col items-center gap-4">
              <span className={`text-[13px] font-black uppercase tracking-[0.8em] transition-all duration-700 ${isListening ? 'text-blue-400 drop-shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'text-slate-700'}`}>
                {isListening ? 'FEED ACTIVE' : 'INITIATE LINK'}
              </span>
            </div>
          </button>
        )}
      </div>

      {/* Diagnostics HUD */}
      <div className="w-full space-y-10">
        <div className="flex justify-between items-center px-8">
          <div className="flex items-center gap-5 px-8 py-4 rounded-full bg-slate-950 border border-white/5 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] backdrop-blur-3xl shadow-2xl">
             <div className={`w-3 h-3 rounded-full ${isListening ? 'bg-emerald-400 animate-ping shadow-[0_0_10px_#10b981]' : 'bg-slate-800'}`} />
             {status}
          </div>
