        {error && (
          <div className="flex items-center gap-8 p-10 bg-red-500/5 border border-red-500/10 rounded-[4rem] animate-in slide-in-from-top-10 duration-700 shadow-2xl">
            <div className="p-5 bg-red-500/10 rounded-[2rem] shadow-inner"><AlertCircle className="text-red-500" size={40} /></div>
            <div className="flex-1 space-y-3">
              <p className="text-red-400 text-xs font-black uppercase tracking-[0.5em]">Critical Handshake Error</p>
