            </div>
            {error.toLowerCase().includes('key') && (
              <button onClick={handleOpenKeySelector} className="px-10 py-4 bg-red-600/20 hover:bg-red-600/40 text-red-100 text-[10px] font-black uppercase tracking-widest rounded-full border border-red-500/30 transition-all">Re-link</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default VoiceInteraction;

